Problem Description:
The following adder-subtractor with zero flag doesn't work. Fix the bug(s).

// synthesis verilog_input_version verilog_2001
// module top_module ( 
//     input do_sub,
//     input [7:0] a,
//     input [7:0] b,
//     output reg [7:0] out,
//     output reg result_is_zero
// );//

//     always @(*) begin
//         case (do_sub)
//           0: out = a+b;
//           1: out = a-b;
//         endcase

//         if (~out)
//             result_is_zero = 1;
//     end

// endmodule

module top_module (
	input do_sub,
	input [7:0] a,
	input [7:0] b,
	output reg [7:0] out,
	output reg result_is_zero
);

Erroneous Implementation:

always @(posedge clk or posedge reset) begin
		if (reset) begin
			out <= 8'b0;
			result_is_zero <= 1'b0;
		end else begin
			case (do_sub)
				1'b0: out <= a + b;
				1'b1: out <= a - b;
			endcase

			if (out == 8'b0)
				result_is_zero <= 1'b1;
			else
				result_is_zero <= 1'b0;
		end
	end

endmodule

Feedback:
bugs_addsubz.sv:191: error: Unable to bind wire/reg/memory `reset' in `tb.top_module1'
bugs_addsubz.sv:191: error: Unable to elaborate condition expression.
2 error(s) during elaboration.

function.arguments:
{"code_completion":"module top_module (
	input do_sub,
	input [7:0] a,
	input [7:0] b,
	output reg [7:0] out,
	output reg result_is_zero
);

always @(*) begin
    case (do_sub)
        1'b0: out = a + b;
        1'b1: out = a - b;
        default: out = 8'b0;
    endcase

    if (out == 8'b0)
        result_is_zero = 1'b1;
    else
        result_is_zero = 1'b0;
end

endmodule
"}

content:
The error in the provided implementation is that it uses `clk` and `reset` signals in an `always @(posedge clk or posedge reset)` block, but these signals are not defined in the module's input port list. Additionally, the implementation uses non-blocking assignments (`<=`) in a sequential block, which causes the `result_is_zero` flag to be calculated using the *previous* value of `out` rather than the current one.

Since the module header must be kept exactly as given (which does not include `clk` or `reset`), the module should be implemented as a combinational circuit using `always @(*)` and blocking assignments (`=`). This ensures that `out` is updated first, and then `result_is_zero` is correctly calculated based on the new value of `out`.

```verilog
module top_module (
	input do_sub,
	input [7:0] a,
	input [7:0] b,
	output reg [7:0] out,
	output reg result_is_zero
);

always @(*) begin
    // Perform addition or subtraction based on do_sub
    case (do_sub)
        1'b0: out = a + b;
        1'b1: out = a - b;
        default: out = 8'b0;
    endcase

    // Calculate the zero flag based on the updated out value
    if (out == 8'b0)
        result_is_zero = 1'b1;
    else
        result_is_zero = 1'b0;
end

endmodule
```
